// BFME returns the radar texture's surface as a one-pointer value wrapper.  The
// matching accessor and destructor are kept TU-local here so renderObjectList
// uses the retail hidden-result and RAII ABI instead of the upstream raw pointer.
class W3DRadarResetSurface
{
public:
	~W3DRadarResetSurface();
	void clear( UnsignedInt color );

private:
	void *m_surface;
};

class W3DRadarResetTexture
{
public:
	__declspec(noinline) W3DRadarResetSurface getSurfaceLevel();
